#include <vector>
#include <iostream>

int main() {
    std::vector<int> populated = {10, 20, 30};
    std::vector<int> empty_v;

    // Correct usage
    std::cout << "First element: " << populated.front() << std::endl;

    // Check precondition is mandatory
    if (empty_v.empty()) {
        std::cout << "Container is empty, cannot use front()\n";
    }

    // empty_v.front(); // UNDEFINED BEHAVIOR: Precondition violated

    // Safe equivalent pattern
    if (!populated.empty()) {
        int& last = populated.back();
        last = 99;
        std::cout << "New last element: " << populated.back() << std::endl;
    }
}
